import asyncio


async def _stub(url):
    await asyncio.sleep(0)
    return "OK:" + url


async def _fetch_all_async(urls, fetcher):
    tasks = [fetcher(url) for url in urls]
    responses = await asyncio.gather(*tasks)
    return list(responses)


def fetch_all(urls, fetcher=None):
    if len(urls) == 0:
        return []
    return asyncio.run(_fetch_all_async(urls, fetcher or _stub))
